-- Aufgaben nachliefern (22.11., Bau-Auftrag FP): frische Übungen der Stufen 2–3 für drei Etappen.
-- Quelle: inhalte/generatoren/_frisch_2211.py (Lösungen berechnet), Dateien inhalte/themen/zahlen.ganz.json und gleichungen.linear.json.
-- Nur für den Haupt-Chat; NICHT von lehrplan-lb ausgeführt. In einer Transaktion einspielen.
-- Nur INSERT über schule.aufgaben_einfuegen (Trigger aufgabe_schutz verbietet bei freigegebenen Einheiten nur UPDATE/DELETE;
-- die Einheit selbst wird nicht verändert, ihr inhalt bleibt gleich). Wiederholt ausführbar: Vorhandenes wird nicht doppelt eingefügt.
-- Die neuen Aufgaben sind sofort für die Kinder sichtbar (Spalte freigegeben, Standard true).
-- Statt schule.einheit_abgleichen, weil diese auch den inhalt der Einheit neu schreibt (bei freigegebenen Einheiten nur erlaubt,
-- wenn er gleich bleibt) und den Typ g nicht mitnimmt.

-- Einheit 39 (zahlen.ganz): 16 neue Übungen (zahlengerade, ordnen)
do $frisch$
declare v_status text; v_max int; v_auf jsonb; v_n int;
begin
  select status into v_status from schule.einheit where id = 39 and thema_id = 16;
  if v_status is null then raise exception 'Einheit 39 gehört nicht zu Thema 16'; end if;
  select coalesce(max(reihenfolge), 0) into v_max from schule.aufgabe where einheit_id = 39 and pool = 'uebung';
  select jsonb_agg(x.a || jsonb_build_object('r', v_max + x.nr)) into v_auf
    from jsonb_array_elements($auf$[{"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "y": "markierung", "f": {"text": "Eine Höhenskala an einer Steilküste reicht von −60 m (Meeresgrund) bis 90 m (Klippe) in 10 gleichen Abschnitten. Tippe an, wo −30 m liegt.", "grafik": {"typ": "zahlenstrahl", "start": -60, "ende": 90, "abschnitte": 10, "beschriftet": "anfang_ende"}}, "o": {"index": 2}, "h": "Wie viele Meter ist ein Abschnitt wert? Zähle dann vom Meeresgrund aus.", "w": "Von −60 bis 90 sind es 150 m, verteilt auf 10 Abschnitte: 15 m je Abschnitt. −30 m liegt 2 Abschnitte rechts von −60 m.", "g": "einkleidung"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Auf einer Zahlengeraden ist jeder Abschnitt 4 wert. Der Punkt P liegt 7 Abschnitte links von 6. Welche Zahl gehört zu P?"}, "o": {"wert": -22}, "h": "Wie weit ist P insgesamt von der Zahl entfernt? Nach links heißt: kleiner werden.", "w": "7 Abschnitte zu je 4 sind 28. 6 − 28 = −22.", "g": "mehrschritt"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Genau in der Mitte zwischen −14 und einer zweiten Zahl liegt −5. Wie heißt die zweite Zahl?"}, "o": {"wert": 4}, "h": "Wie weit ist es von der ersten Zahl bis zur Mitte? Genauso weit geht es auf der anderen Seite weiter.", "w": "Von −14 bis −5 sind es 9 Schritte nach rechts. Noch einmal 9 Schritte: −5 + 9 = 4.", "g": "umkehr"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Eine Zahlengerade beginnt bei −12 und endet bei 18. Dazwischen liegen 6 gleich lange Abschnitte. Welche Zahlen stehen an den Strichen?"}, "a": ["−12, −6, 0, 6, 12, 18", "−12, −9, −6, −3, 0, 3, 6", "−12, −7, −2, 3, 8, 13, 18", "−12, −7, −2, 2, 7, 12, 18"], "o": {"index": 2}, "h": "Rechne zuerst aus, wie viel ein Abschnitt wert ist. Zähle dann vom Anfang aus weiter – auch über die 0 hinweg.", "w": "Von −12 bis 18 sind es 30, verteilt auf 6 Abschnitte: 5 je Abschnitt. Also −12, −7, −2, 3, 8, 13, 18.", "g": "darstellung"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Punkt wird auf der Zahlengeraden erst um 9 nach rechts und danach um 15 nach links geschoben. Jetzt liegt er bei −11. Wo lag er am Anfang?"}, "o": {"wert": -5}, "h": "Geh die Wege rückwärts: Was zuletzt passiert ist, machst du zuerst rückgängig – in die andere Richtung.", "w": "Rückwärts: von −11 um 15 nach rechts: 4. Dann um 9 nach links: −5. Probe: −5 + 9 − 15 = −11.", "g": "rueckwaerts"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Stimmt die Aussage? „Liegt a auf der Zahlengeraden links von b, dann liegt auch −a links von −b.“"}, "a": ["Ja, das gilt immer.", "Nein. Das Spiegeln an der 0 vertauscht die Seiten: −a liegt dann rechts von −b.", "Nur wenn a und b beide negativ sind.", "Nur wenn a und b beide positiv sind."], "o": {"index": 1}, "h": "Probiere es mit zwei Zahlen aus, zum Beispiel a = 2 und b = 5. Wo liegen −2 und −5?", "w": "2 liegt links von 5, aber −2 liegt rechts von −5. Gegenzahlen sind an der 0 gespiegelt; dabei werden links und rechts vertauscht.", "g": "begruenden"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Für welche Zahl a liegt −3 genau in der Mitte zwischen a und 2 · a?"}, "o": {"wert": -2}, "h": "Die Mitte zweier Zahlen ist ihre Summe geteilt durch 2. Stelle damit eine Gleichung für a auf.", "w": "Mitte: (a + 2a) : 2 = 3a : 2 = −3. Also 3a = −6 und a = −2. Probe: zwischen −2 und −4 liegt −3 in der Mitte.", "g": "parameter"}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Jemand sucht die Mitte zwischen −18 und 6 und rechnet: (18 + 6) : 2 = 12. Was ist falsch?"}, "a": ["Man muss subtrahieren: (18 − 6) : 2 = 6.", "Nichts, 12 stimmt.", "Man muss durch 3 teilen, nicht durch 2.", "Das Minus von −18 fehlt. Richtig ist (−18 + 6) : 2 = −6."], "o": {"index": 3}, "h": "Kann die Mitte zwischen einer negativen und einer kleineren positiven Zahl größer als beide sein?", "w": "Die Mitte muss zwischen −18 und 6 liegen; 12 liegt rechts von beiden. Mit dem Vorzeichen: (−18 + 6) : 2 = −6.", "g": "fehler"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Kontostand am Monatsende: Januar −35 €, Februar 12 €, März −80 €, April −5 €. Wie hoch war der niedrigste Kontostand?"}, "o": {"wert": -80, "einheit": "€"}, "h": "Der niedrigste Stand ist die kleinste Zahl. Bei negativen Zahlen: Je weiter weg von 0, desto kleiner.", "w": "Negativ sind −35, −80, −5. Am weitesten von 0 entfernt ist −80. Also ist −80 € der niedrigste Stand.", "g": "einkleidung"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Ordne −6, 4, −15, 0, −1 von der größten zur kleinsten Zahl. Welche Reihe stimmt?"}, "a": ["4 > 0 > −1 > −6 > −15", "4 > 0 > −15 > −6 > −1", "−15 > −6 > −1 > 0 > 4", "4 > −1 > 0 > −6 > −15"], "o": {"index": 0}, "h": "Zuerst die positiven Zahlen, dann die 0, dann die negativen: Bei ihnen kommt die mit dem kleinsten Betrag zuerst.", "w": "Positiv: 4. Dann 0. Negativ, von nah an 0 nach weit weg: −1, −6, −15. Also 4 > 0 > −1 > −6 > −15.", "g": "mehrschritt"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Zwischen −14 und einer größeren ganzen Zahl b liegen genau 5 ganze Zahlen. Welche Zahl ist b?"}, "o": {"wert": -8}, "h": "Zähle von der ersten Zahl aus nach rechts weiter, ohne sie selbst mitzuzählen.", "w": "Dazwischen liegen −13, −12, −11, −10, −9 – das sind 5. Die nächste Zahl ist b = −8.", "g": "umkehr"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Auf einer Zahlengeraden liegen die Punkte A, B und C von links nach rechts. Zu ihnen gehören die Zahlen −2, −11, 5 – nicht unbedingt in dieser Reihenfolge. Welche Zahl gehört zu B?"}, "a": ["−11", "−2", "5", "Das kann man nicht sagen."], "o": {"index": 1}, "h": "Links liegt die kleinste Zahl. B ist der mittlere Punkt.", "w": "Geordnet: −11 < −2 < 5. A = −11, B = −2, C = 5.", "g": "darstellung"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Bei einem Spiel gewinnt, wer am Ende den kleinsten Punktestand hat. Die Endstände sind −12, −30, 4, −7. Auf welchem Platz landet der Spieler mit −7 Punkten?"}, "a": ["Platz 1", "Platz 2", "Platz 3", "Platz 4"], "o": {"index": 2}, "h": "Platz 1 hat die kleinste Zahl. Ordne alle Stände von klein nach groß.", "w": "Von klein nach groß: −30 < −12 < −7 < 4. −7 steht an Stelle 3, also Platz 3.", "g": "transfer"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Stimmt die Aussage? „Jede negative Zahl ist kleiner als jede positive Zahl.“"}, "a": ["Nein: −100 ist größer als 1, weil 100 größer ist als 1.", "Nur wenn die negative Zahl den kleineren Betrag hat.", "Ja. Negative Zahlen liegen links von 0, positive rechts davon.", "Nein: −5 und 5 sind gleich groß, weil sie denselben Betrag haben."], "o": {"index": 2}, "h": "Denk an die Zahlengerade: Wo liegen negative, wo positive Zahlen – und wo die 0?", "w": "Alle negativen Zahlen liegen links von 0, alle positiven rechts. Links bedeutet kleiner. Die Aussage stimmt; der Betrag spielt beim Vergleich mit 0 keine Rolle.", "g": "begruenden"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "a ist eine ganze Zahl mit −9 < a < −3. Welchen Wert kann a höchstens haben?"}, "o": {"wert": -4}, "h": "a muss kleiner als −3 sein. Welche ganze Zahl kommt direkt links von −3?", "w": "Möglich sind −8, −7, −6, −5, −4. Die größte davon ist −4.", "g": "parameter"}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Eine Liste soll Temperaturen von warm nach kalt ordnen: 4 °C, −1 °C, −12 °C, −7 °C. Wo steckt der Fehler?"}, "a": ["4 °C und −1 °C sind vertauscht.", "−12 °C und −7 °C sind vertauscht.", "−1 °C und −12 °C sind vertauscht.", "Alles ist richtig geordnet."], "o": {"index": 1}, "h": "Prüfe jedes Paar nebeneinander: Ist die erste Temperatur wirklich wärmer als die zweite?", "w": "4 > −1 stimmt, −1 > −12 stimmt, aber −12 > −7 stimmt nicht: −7 °C ist wärmer. Richtig: 4 °C, −1 °C, −7 °C, −12 °C.", "g": "fehler"}]$auf$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(39, v_auf);   -- fügt nur ein, was es (Frage + Antworten) noch nicht gibt
  raise notice 'Einheit 39 (%): % von 16 neuen Übungen eingefügt (0 = schon vorhanden)', v_status, v_n;
  if v_n not in (0, 16) then raise exception 'Einheit 39: nur % von 16 eingefügt – teilweise vorhanden, bitte prüfen', v_n; end if;
end $frisch$;

-- Einheit 5 (gleichungen.linear): 8 neue Übungen (waage)
do $frisch$
declare v_status text; v_max int; v_auf jsonb; v_n int;
begin
  select status into v_status from schule.einheit where id = 5 and thema_id = 2;
  if v_status is null then raise exception 'Einheit 5 gehört nicht zu Thema 2'; end if;
  select coalesce(max(reihenfolge), 0) into v_max from schule.aufgabe where einheit_id = 5 and pool = 'uebung';
  select jsonb_agg(x.a || jsonb_build_object('r', v_max + x.nr)) into v_auf
    from jsonb_array_elements($auf$[{"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Ein Paket mit 5 gleich schweren Büchern wiegt zusammen mit der Verpackung von 300 g genau 2,3 kg. Wie viel Gramm wiegt ein Buch?"}, "o": {"wert": 400, "einheit": "g"}, "h": "Rechne 2,3 kg in Gramm um und stelle eine Gleichung auf: Bücher plus Verpackung ergeben das Gesamtgewicht.", "w": "2,3 kg = 2300 g. Gleichung: 5x + 300 = 2300. | − 300: 5x = 2000. | : 5: x = 400. Ein Buch wiegt 400 g.", "g": "einkleidung"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "y": "auswahl", "f": {"text": "Auf der linken Waagschale liegen 2 gleiche Dosen und 3 Ein-Kilo-Gewichte, auf der rechten 11 Ein-Kilo-Gewichte. Die Waage ist im Gleichgewicht. Welche Gleichung passt, wenn x das Gewicht einer Dose in kg ist?"}, "a": ["2x = 11 + 3", "2 + 3x = 11", "2x + 3 = 11", "x + 3 = 11"], "o": {"index": 2}, "h": "Schreibe auf, was links liegt, und setze es gleich dem, was rechts liegt.", "w": "Links: 2 Dosen = 2x, dazu 3 kg. Rechts: 11 kg. Also 2x + 3 = 11 (und damit x = 4).", "g": "darstellung"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Die Gleichung □ · x + 5 = −19 hat die Lösung x = −6. Welche Zahl steht im Kästchen?"}, "o": {"wert": 4}, "h": "Setze x = −6 ein. Dann bleibt eine Gleichung, in der nur noch die Zahl im Kästchen fehlt.", "w": "□ · (−6) + 5 = −19. | − 5: □ · (−6) = −24. | : (−6): □ = 4. Probe: 4 · (−6) + 5 = −19 ✓", "g": "umkehr"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "y": "zahl", "f": {"text": "Welchen Wert hat x, wenn 1,5x − 4 = 5 gilt?"}, "o": {"wert": 6}, "h": "Erst die Zahl ohne x auf die andere Seite bringen, dann durch die Zahl vor dem x teilen.", "w": "| + 4: 1,5x = 9. | : 1,5: x = 6. Probe: 1,5 · 6 − 4 = 5 ✓", "g": "mehrschritt"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Jemand löst 5x + 12 = −3 so: „| − 12: 5x = 9. | : 5: x = 1,8.“ Wo steckt der Fehler?"}, "a": ["Falsch gerechnet: −3 − 12 = −15, nicht 9. Richtig ist x = −3.", "Man hätte zuerst durch 5 teilen müssen.", "9 : 5 ist nicht 1,8.", "Es ist kein Fehler drin."], "o": {"index": 0}, "h": "Mach die Probe mit x = 1,8 in der ursprünglichen Gleichung. Prüfe dann jeden Schritt einzeln.", "w": "Probe: 5 · 1,8 + 12 = 21, nicht −3. Der Fehler: −3 − 12 ist −15. Dann 5x = −15 und x = −3.", "g": "fehler"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Preis wird um 20 % gesenkt, danach werden noch 4 € abgezogen. Jetzt kostet die Ware 36 €. Wie viel kostete sie vorher?"}, "o": {"wert": 50, "einheit": "€"}, "h": "Nach 20 % Rabatt bleiben 80 % vom Preis, also 0,8 · x. Stelle damit eine Gleichung auf.", "w": "0,8x − 4 = 36. | + 4: 0,8x = 40. | : 0,8: x = 50. Probe: 80 % von 50 € sind 40 €, minus 4 € = 36 € ✓", "g": "verknuepfen"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "y": "auswahl", "f": {"text": "Darf man beim Lösen einer Gleichung beide Seiten mit 0 multiplizieren?"}, "a": ["Ja, das ist eine Äquivalenzumformung wie jede andere.", "Ja, aber nur, wenn x negativ ist.", "Nein, weil man bei Gleichungen nur addieren und subtrahieren darf.", "Nein. Dann steht auf beiden Seiten 0, und jede Zahl würde passen – die Lösung geht verloren."], "o": {"index": 3}, "h": "Probiere es an 2x = 6 aus. Was steht nach dem Multiplizieren mit 0 da, und welche Zahlen erfüllen das?", "w": "2x = 6 hat die Lösung 3. Mal 0 ergibt 0 = 0 – das gilt für jede Zahl. Die Umformung verändert also die Lösungsmenge; mit 0 multiplizieren ist keine Äquivalenzumformung.", "g": "begruenden"}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "y": "zahl", "f": {"text": "Ein Handytarif kostet 9 € Grundgebühr im Monat und 15 Cent je Minute. Im März waren es 14,40 €. Wie viele Minuten wurde telefoniert?"}, "o": {"wert": 36}, "h": "Stelle eine Gleichung auf: Grundgebühr plus Minuten mal Preis je Minute ergibt den Betrag. Rechne am besten in Cent.", "w": "In Cent: 900 + 15x = 1440. | − 900: 15x = 540. | : 15: x = 36. Es waren 36 Minuten.", "g": "transfer"}]$auf$::jsonb) with ordinality x(a, nr);
  v_n := schule.aufgaben_einfuegen(5, v_auf);   -- fügt nur ein, was es (Frage + Antworten) noch nicht gibt
  raise notice 'Einheit 5 (%): % von 8 neuen Übungen eingefügt (0 = schon vorhanden)', v_status, v_n;
  if v_n not in (0, 8) then raise exception 'Einheit 5: nur % von 8 eingefügt – teilweise vorhanden, bitte prüfen', v_n; end if;
end $frisch$;

-- Rauchtest (liest nur)
do $pruef$
declare v_txt text;
begin
  select string_agg(format('%s/%s: %s', einheit_id, variante_gruppe, n), ', ') into v_txt from (
    select einheit_id, variante_gruppe, count(*) n from schule.aufgabe
     where pool = 'uebung' and stufe in (2, 3) and freigegeben and typ is not null
       and ((einheit_id = 39 and variante_gruppe in ('zahlengerade', 'ordnen')) or (einheit_id = 5 and variante_gruppe = 'waage'))
       and frage->>'text' in ('Eine Höhenskala an einer Steilküste reicht von −60 m (Meeresgrund) bis 90 m (Klippe) in 10 gleichen Abschnitten. Tippe an, wo −30 m liegt.', 'Auf einer Zahlengeraden ist jeder Abschnitt 4 wert. Der Punkt P liegt 7 Abschnitte links von 6. Welche Zahl gehört zu P?', 'Genau in der Mitte zwischen −14 und einer zweiten Zahl liegt −5. Wie heißt die zweite Zahl?', 'Eine Zahlengerade beginnt bei −12 und endet bei 18. Dazwischen liegen 6 gleich lange Abschnitte. Welche Zahlen stehen an den Strichen?', 'Ein Punkt wird auf der Zahlengeraden erst um 9 nach rechts und danach um 15 nach links geschoben. Jetzt liegt er bei −11. Wo lag er am Anfang?', 'Stimmt die Aussage? „Liegt a auf der Zahlengeraden links von b, dann liegt auch −a links von −b.“', 'Für welche Zahl a liegt −3 genau in der Mitte zwischen a und 2 · a?', 'Jemand sucht die Mitte zwischen −18 und 6 und rechnet: (18 + 6) : 2 = 12. Was ist falsch?', 'Kontostand am Monatsende: Januar −35 €, Februar 12 €, März −80 €, April −5 €. Wie hoch war der niedrigste Kontostand?', 'Ordne −6, 4, −15, 0, −1 von der größten zur kleinsten Zahl. Welche Reihe stimmt?', 'Zwischen −14 und einer größeren ganzen Zahl b liegen genau 5 ganze Zahlen. Welche Zahl ist b?', 'Auf einer Zahlengeraden liegen die Punkte A, B und C von links nach rechts. Zu ihnen gehören die Zahlen −2, −11, 5 – nicht unbedingt in dieser Reihenfolge. Welche Zahl gehört zu B?', 'Bei einem Spiel gewinnt, wer am Ende den kleinsten Punktestand hat. Die Endstände sind −12, −30, 4, −7. Auf welchem Platz landet der Spieler mit −7 Punkten?', 'Stimmt die Aussage? „Jede negative Zahl ist kleiner als jede positive Zahl.“', 'a ist eine ganze Zahl mit −9 < a < −3. Welchen Wert kann a höchstens haben?', 'Eine Liste soll Temperaturen von warm nach kalt ordnen: 4 °C, −1 °C, −12 °C, −7 °C. Wo steckt der Fehler?', 'Ein Paket mit 5 gleich schweren Büchern wiegt zusammen mit der Verpackung von 300 g genau 2,3 kg. Wie viel Gramm wiegt ein Buch?', 'Auf der linken Waagschale liegen 2 gleiche Dosen und 3 Ein-Kilo-Gewichte, auf der rechten 11 Ein-Kilo-Gewichte. Die Waage ist im Gleichgewicht. Welche Gleichung passt, wenn x das Gewicht einer Dose in kg ist?', 'Die Gleichung □ · x + 5 = −19 hat die Lösung x = −6. Welche Zahl steht im Kästchen?', 'Welchen Wert hat x, wenn 1,5x − 4 = 5 gilt?', 'Jemand löst 5x + 12 = −3 so: „| − 12: 5x = 9. | : 5: x = 1,8.“ Wo steckt der Fehler?', 'Ein Preis wird um 20 % gesenkt, danach werden noch 4 € abgezogen. Jetzt kostet die Ware 36 €. Wie viel kostete sie vorher?', 'Darf man beim Lösen einer Gleichung beide Seiten mit 0 multiplizieren?', 'Ein Handytarif kostet 9 € Grundgebühr im Monat und 15 Cent je Minute. Im März waren es 14,40 €. Wie viele Minuten wurde telefoniert?')
     group by 1, 2) x where n <> 8;
  if v_txt is not null then raise exception 'Rauchtest: nicht je 8 neue Übungen: %', v_txt; end if;
  if (select count(*) from schule.aufgabe where frage->>'text' in ('Eine Höhenskala an einer Steilküste reicht von −60 m (Meeresgrund) bis 90 m (Klippe) in 10 gleichen Abschnitten. Tippe an, wo −30 m liegt.', 'Auf einer Zahlengeraden ist jeder Abschnitt 4 wert. Der Punkt P liegt 7 Abschnitte links von 6. Welche Zahl gehört zu P?', 'Genau in der Mitte zwischen −14 und einer zweiten Zahl liegt −5. Wie heißt die zweite Zahl?', 'Eine Zahlengerade beginnt bei −12 und endet bei 18. Dazwischen liegen 6 gleich lange Abschnitte. Welche Zahlen stehen an den Strichen?', 'Ein Punkt wird auf der Zahlengeraden erst um 9 nach rechts und danach um 15 nach links geschoben. Jetzt liegt er bei −11. Wo lag er am Anfang?', 'Stimmt die Aussage? „Liegt a auf der Zahlengeraden links von b, dann liegt auch −a links von −b.“', 'Für welche Zahl a liegt −3 genau in der Mitte zwischen a und 2 · a?', 'Jemand sucht die Mitte zwischen −18 und 6 und rechnet: (18 + 6) : 2 = 12. Was ist falsch?', 'Kontostand am Monatsende: Januar −35 €, Februar 12 €, März −80 €, April −5 €. Wie hoch war der niedrigste Kontostand?', 'Ordne −6, 4, −15, 0, −1 von der größten zur kleinsten Zahl. Welche Reihe stimmt?', 'Zwischen −14 und einer größeren ganzen Zahl b liegen genau 5 ganze Zahlen. Welche Zahl ist b?', 'Auf einer Zahlengeraden liegen die Punkte A, B und C von links nach rechts. Zu ihnen gehören die Zahlen −2, −11, 5 – nicht unbedingt in dieser Reihenfolge. Welche Zahl gehört zu B?', 'Bei einem Spiel gewinnt, wer am Ende den kleinsten Punktestand hat. Die Endstände sind −12, −30, 4, −7. Auf welchem Platz landet der Spieler mit −7 Punkten?', 'Stimmt die Aussage? „Jede negative Zahl ist kleiner als jede positive Zahl.“', 'a ist eine ganze Zahl mit −9 < a < −3. Welchen Wert kann a höchstens haben?', 'Eine Liste soll Temperaturen von warm nach kalt ordnen: 4 °C, −1 °C, −12 °C, −7 °C. Wo steckt der Fehler?', 'Ein Paket mit 5 gleich schweren Büchern wiegt zusammen mit der Verpackung von 300 g genau 2,3 kg. Wie viel Gramm wiegt ein Buch?', 'Auf der linken Waagschale liegen 2 gleiche Dosen und 3 Ein-Kilo-Gewichte, auf der rechten 11 Ein-Kilo-Gewichte. Die Waage ist im Gleichgewicht. Welche Gleichung passt, wenn x das Gewicht einer Dose in kg ist?', 'Die Gleichung □ · x + 5 = −19 hat die Lösung x = −6. Welche Zahl steht im Kästchen?', 'Welchen Wert hat x, wenn 1,5x − 4 = 5 gilt?', 'Jemand löst 5x + 12 = −3 so: „| − 12: 5x = 9. | : 5: x = 1,8.“ Wo steckt der Fehler?', 'Ein Preis wird um 20 % gesenkt, danach werden noch 4 € abgezogen. Jetzt kostet die Ware 36 €. Wie viel kostete sie vorher?', 'Darf man beim Lösen einer Gleichung beide Seiten mit 0 multiplizieren?', 'Ein Handytarif kostet 9 € Grundgebühr im Monat und 15 Cent je Minute. Im März waren es 14,40 €. Wie viele Minuten wurde telefoniert?')
        and ((einheit_id = 39 and variante_gruppe in ('zahlengerade', 'ordnen')) or (einheit_id = 5 and variante_gruppe = 'waage'))) <> 24 then
    raise exception 'Rauchtest: Zahl der neuen Übungen ist nicht 24';
  end if;
  raise notice 'Rauchtest Aufgaben frisch bestanden: je Etappe 8 neue Übungen (Stufe 2–3, mit Typ, freigegeben)';
end $pruef$;
